/*
 * GSM MQTT Publisher — Board 1
 * Publishes temperature readings to 'ardusim/temp' every 5 seconds
 * and subscribes to 'ardusim/led' for LED control commands.
 * Uses SIM800/SIM900 GSM module with MQTT over cellular.
 */

#include <GSM.h>

GSM gsm;

const char* mqttBroker = "broker.emqx.io";
const int   mqttPort   = 1883;
const char* clientId   = "ArduinoUno_Publisher";
const char* topicTemp  = "ardusim/temp";
const char* topicLed   = "ardusim/led";

int tempC = 20;
int msgCount = 0;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  Serial.println("GSM MQTT Publisher Starting...");

  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);

  // Initialize GSM module
  gsm.begin();

  // Connect to MQTT broker
  gsm.mqttConnect(mqttBroker, mqttPort, clientId);

  // Subscribe to LED control topic
  gsm.mqttSubscribe(topicLed);

  Serial.println("GSM MQTT Publisher ready!");
  Serial.println("IMEI: " + gsm.getIMEI());
  Serial.println("---");
}

void loop() {
  // Process any incoming MQTT messages (LED on/off commands)
  int msgs = gsm.mqttLoop();

  // Publish temperature reading
  tempC = 20 + (msgCount % 10);
  msgCount++;

  Serial.print("Publishing temperature: ");
  Serial.print(tempC);
  Serial.println(" °C");

  gsm.mqttPublish(topicTemp, String(tempC));

  // Toggle built-in LED to show activity
  digitalWrite(13, !digitalRead(13));

  Serial.println("---");
  delay(5000);
}

