/*
 * GSM MQTT Subscriber — Board 2
 * Subscribes to 'ardusim/temp' for temperature readings
 * and publishes LED state to 'ardusim/led'.
 * Uses SIM800/SIM900 GSM module with MQTT over cellular.
 */

#include <GSM.h>

GSM gsm;

const char* mqttBroker = "broker.emqx.io";
const int   mqttPort   = 1883;
const char* clientId   = "ArduinoUno_Subscriber";
const char* topicTemp  = "ardusim/temp";
const char* topicLed   = "ardusim/led";

bool ledState = false;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  Serial.println("GSM MQTT Subscriber Starting...");

  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);

  // Initialize GSM module
  gsm.begin();

  // Connect to MQTT broker
  gsm.mqttConnect(mqttBroker, mqttPort, clientId);

  // Subscribe to temperature topic
  gsm.mqttSubscribe(topicTemp);

  Serial.println("GSM MQTT Subscriber ready!");
  Serial.println("IMEI: " + gsm.getIMEI());
  Serial.println("---");
}

void loop() {
  // Process incoming MQTT messages
  int msgs = gsm.mqttLoop();

  // Toggle LED state and publish every 6 seconds
  static unsigned long lastPublish = 0;
  unsigned long now = millis();
  if (now - lastPublish > 6000) {
    lastPublish = now;
    ledState = !ledState;
    digitalWrite(13, ledState ? HIGH : LOW);

    Serial.print("Publishing LED state: ");
    Serial.println(ledState ? "ON" : "OFF");

    gsm.mqttPublish(topicLed, ledState ? "on" : "off");
    Serial.println("---");
  }

  delay(500);
}
